import{z as A,x as B,o as n,c as d,q as l,j as r,D as e,d as i,s,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Calvin 确定性","description":"","frontmatter":{"title":"Calvin 确定性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/calvin-deterministic.md","filePath":"cs/calvin-deterministic.md","lastUpdated":1791413859000}'),p={name:"cs/calvin-deterministic.md"};function C(m,a,D,c,h,u){const t=B("Mermaid");return n(),d("div",null,[a[2]||(a[2]=l('<h1 id="calvin-确定性" tabindex="-1">Calvin 确定性 <a class="header-anchor" href="#calvin-确定性" aria-label="Permalink to &quot;Calvin 确定性&quot;">​</a></h1><div class="epigraph"><p>先对事务输入全局排序再执行：同一日志在每个副本上重放同一调度，锁可在定序后无死锁获取，提交无需 2PC 对话。</p><footer>—— 据 Thomson et al., Calvin, SIGMOD 2012；确定性数据库谱系</footer></div><p><a href="/cs/read-only-snapshot">上一课</a>把只读从写路径拆开。本课不钉 xmin。缺口是分布式写：2PC 阻塞、死锁跨节点。Calvin 一类确定性数据库：先把事务（或锁请求集）写入全局有序日志（Paxos），再按序执行。并发控制续封口；恢复复制续从 ARIES 三阶段开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>非确定性：各节点本地 2PL 调度不同，副本不能只重放 SQL 文本。确定性：输入序列唯一决定调度与结果。缺口是<strong>读集必须先声明或先侦察</strong>：否则定序时不知道锁哪些键。只读可走本地快照，但要与定序水位一致。</p><p>与 OCC：Calvin 减少 abort，把冲突变成队列里的顺序。热点键仍串行，只是顺序明确。</p><p><span class="marginnote">Thomson, Diamond, Weng, Ren, Shao, Abadi, SIGMOD 2012。后续 Fauna 等。本课机制，不把产品当标准。Spanner 用真时间戳，路线不同，后课。</span></p><p><span class="marginnote">直觉类比：侦察事务像正式演出前的彩排——先空跑一遍，把要碰的道具（读集）记下来；代价是多跑一遍、延迟翻倍，换来定序时明确知道该锁哪些键。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>客户端提交事务批次 → 定序器编号 → 工作机按号获取锁（无等待环：按键排序加锁）→ 执行 → 提交。失败：确定性重放或标记 abort 占住序号。</p><p>与 WAL：全局日志即事务输入日志，重做是再执行而非生理 redo——粒度不同，恢复课对照影子与生理。</p>',11)),(n(),r(o,null,{default:e(()=>[s(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E4%BA%8B%E5%8A%A1%E8%BE%93%E5%85%A5%22%5D%20--%3E%20SEQ%5B%22%E5%85%A8%E5%B1%80%E5%AE%9A%E5%BA%8F%E6%97%A5%E5%BF%97%22%5D%0A%20%20SEQ%20--%3E%20LOCK%5B%22%E6%8C%89%E5%BA%8F%E6%8C%89%E9%94%AE%E5%8A%A0%E9%94%81%22%5D%0A%20%20LOCK%20--%3E%20EX%5B%22%E6%89%A7%E8%A1%8C%22%5D%0A%20%20EX%20--%3E%20REP%5B%22%E5%89%AF%E6%9C%AC%E5%90%8C%E4%B8%80%E8%B0%83%E5%BA%A6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"依赖分析：无锁冲突的事务可并行执行仍等价于序。侦察事务先跑一遍读集再定序，增加延迟。与 MVCC：可在定序戳上读版本。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"术语翻译：确定性就是用「同一份输入日志在任何副本上重放出同一个调度」的手段来做「免协调复制」的事——副本不用投票表决结果，因为定序那一刻结果就唯一了，重放即可对齐。")],-1)),a[6]||(a[6]=E("p",null,"性能：定序器吞吐是上限；可分区定序但跨分区事务又要合成序。",-1)),(n(),r(o,null,{default:e(()=>[s(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E4%BA%8B%E5%8A%A1%20A%20%E6%83%B3%E8%A6%81%E9%94%AE%20x%20%E4%B8%8E%20y%22%5D%20--%3E%20S1%5B%22%E6%8C%89%E9%94%AE%E5%BA%8F%EF%BC%9A%E5%85%88%20x%20%E5%90%8E%20y%22%5D%0A%20%20T2%5B%22%E4%BA%8B%E5%8A%A1%20B%20%E6%83%B3%E8%A6%81%E9%94%AE%20y%20%E4%B8%8E%20x%22%5D%20--%3E%20S2%5B%22%E5%90%8C%E6%A0%B7%E5%85%88%20x%20%E5%90%8E%20y%22%5D%0A%20%20S1%20--%3E%20X%5B%22%E8%B0%81%E5%85%88%E6%8B%BF%E5%88%B0%20x%20%E8%B0%81%E5%85%88%E8%B5%B0%22%5D%0A%20%20S2%20--%3E%20X%0A%20%20X%20--%3E%20NO%5B%22%E7%8E%AF%E8%B7%AF%E7%AD%89%E5%BE%85%E6%97%A0%E6%B3%95%E5%BD%A2%E6%88%90%EF%BC%9A%E6%97%A0%E6%AD%BB%E9%94%81%22%5D%0A%20%20BAD%5B%22%E4%B8%8D%E6%8E%92%E5%BA%8F%EF%BC%9AA%20%E6%8C%81%20y%20%E7%AD%89%20x%EF%BC%8CB%20%E6%8C%81%20x%20%E7%AD%89%20y%22%5D%20--%3E%20DEAD%5B%22%E4%BA%92%E7%9B%B8%E7%AD%89%E5%BE%85%EF%BC%8C%E9%9C%80%E6%AD%BB%E9%94%81%E6%A3%80%E6%B5%8B%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">常见误区：初学者容易以为「确定性等于没有等待」，实际上热点键照样串行——只是等待发生在日志队列里、顺序事先已知，而不是执行中互相踩了再 abort 重来一遍。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 ARIES CLR。也不把确定性当「无日志」。网络分区时定序器可用性是共识问题，后课分布式。</p><p>后课默认：可先定序再执行以避免 2PC 与死锁。ARIES 三阶段与 CLR：单机生理恢复的完整播放。</p><p>确定性调度把隔离做成「日志里的全序」，应用仍要可重放（无非确定性 UDF）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Calvin 全局定序事务输入，副本同调度，免 2PC 对话。</li><li>需要读集或侦察；热点仍串行。</li><li>下一序列 ARIES 三阶段与 CLR：崩溃恢复播放。</li><li>出处：Thomson et al. SIGMOD 2012；2PC 对照。</li></ul>',7))])}const _=A(p,[["render",C]]);export{f as __pageData,_ as default};
